    {
      "id": "C02",
      "status": "pass",
      "source_evidence": "The surrounding discussion gives q : ℝ × ℝ → ℝ^m and then specializes to m = 1 with a real constant velocity.",
      "translation_evidence": "The profile, velocity, spatial variable, temporal variable, and derivative values are real; q is a curried real-valued function.",
      "reasoning": "Currying preserves the source domain. Generic vector-space dependencies are specialized to ℝ in the translated proposition."
    },
    {
      "id": "C03",
      "status": "pass",
      "source_evidence": "Equation (1.3) constructs q from an arbitrary profile and a fixed constant velocity.",
      "translation_evidence": "Every f and c determine q; each conclusion ranges over every x and t, and derivative witnesses depend on the evaluation point.",
      "reasoning": "The construction and witness dependence agree. The differentiability antecedent is assessed separately."
    },
    {
      "id": "C04",
      "status": "unclear",
      "source_evidence": "The passage says the formula gives solutions for any function and supplies no explicit regularity hypothesis.",
      "translation_evidence": "The PDE conclusion requires f to be differentiable at every real point.",
      "reasoning": "The translation adds an explicit condition absent from the wording. It is appropriate for a classical interpretation, but the source does not resolve whether that interpretation limits its arbitrary-profile assertion."
    },
    {
      "id": "C05",
      "status": "unclear",
      "source_evidence": "The source asserts both an advection solution and unchanged propagation of the profile.",
      "translation_evidence": "Shape preservation holds unconditionally; existence of partial derivatives satisfying the PDE holds only for everywhere differentiable profiles.",
      "reasoning": "The propagation conclusion is complete. Coverage of the source's solution assertion for other profiles remains unresolved."
    },
    {
      "id": "C06",
      "status": "pass",
      "source_evidence": "Subscripts denote partial derivatives, and equations (1.2)–(1.3) use ordinary real arithmetic.",
      "translation_evidence": "D001–D003 specify the construction and pointwise derivative predicate; D007 and D051 specify differentiability and actual derivative existence. The remaining ledger entries supply ordinary real arithmetic, logical operations, and compatible structures.",
      "reasoning": "The supplied dependency meanings consistently reconstruct ordinary partial derivatives and real multiplication, without default derivative values or altered arithmetic. Whether classical derivatives exhaust the source's intended solution meaning remains a separate ambiguity."
    },
    {
      "id": "C07",
      "status": "unclear",
      "source_evidence": "The profile formula and PDE are exact equalities; the solution assertion is expressed for an arbitrary profile.",
      "translation_evidence": "Both displayed relations are exact equalities, but the PDE relation is conditional on differentiability.",
      "reasoning": "Equality strength matches. Overall implication strength depends on the unresolved regularity and solution interpretation."
    },
    {
      "id": "C08",
      "status": "pass",
      "source_evidence": "The profile q̃ specifies the waveform, and q is its translated space-time realization.",
      "translation_evidence": "f is the original profile, q(x,t) = f(x − ct) is the constructed field, and qt and qx are derivative values.",
      "reasoning": "The original profile, transported field, and derivative witnesses retain distinct roles."
    },
    {
      "id": "C09",
      "status": "pass",
      "source_evidence": "Equations (1.2)–(1.3) have coefficient ū, profile argument x − ūt, and zero right-hand side.",
      "translation_evidence": "The construction uses x − ct and the PDE is qt + c qx = 0.",
      "reasoning": "The coefficient, sign, parameter dependence, and zero match. There are no discrete indices."
    },
    {
      "id": "C10",
      "status": "unclear",
      "source_evidence": "The selected scalar claim uses real space and time and describes the profile as arbitrary.",
      "translation_evidence": "The same scalar field and global domain are retained, but the PDE conclusion applies only under global differentiability.",
      "reasoning": "There is no spatial, temporal, or scalar specialization. The regularity specialization cannot be accepted as source-equivalent without resolving the source's solution notion."
    },
    {
      "id": "C11",
      "status": "unclear",
      "source_evidence": "The passage excludes neither zero nor negative velocity and does not address nondifferentiable profiles despite its arbitrary-profile wording.",
      "translation_evidence": "All real velocities are admitted. Both partial derivatives must exist under the antecedent, including when c = 0; nondifferentiable profiles receive only the propagation identity.",
