    },
    {
      "id": "C12",
      "status": "pass",
      "source_evidence": "The source describes a family of transported profiles.",
      "translation_evidence": "The propagation identity applies to every profile, and the PDE implication applies nonvacuously to everywhere differentiable profiles.",
      "reasoning": "The antecedent is satisfiable, for example by f(x) = x². Its failure for nonsmooth profiles is a scope issue rather than global vacuity."
    },
    {
      "id": "N01",
      "status": "pass",
      "source_evidence": "The profile propagates with constant velocity and unchanged shape.",
      "translation_evidence": "q(x,t) = f(x − ct) and q(x + ct,t) = f(x).",
      "reasoning": "The continuous transport process is exactly the stated translation. No discretization or alternative evolution is introduced."
    },
    {
      "id": "N02",
      "status": "pass",
